#!/usr/bin/env node
/**
 * Copies hardware/joint-map.json into dist/ after a build, so an installed copy
 * of @sesame-lab/sesame-model is self-contained and `loadJointMap()` works
 * without a repository checkout.
 *
 * The repository file stays the single source of truth: it is generated by
 * `node scripts/build-joint-map.mjs` and validated by `pnpm validate:joint-map`.
 * This only ever copies, never edits.
 */
import { copyFileSync, mkdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

const here = dirname(fileURLToPath(import.meta.url));
const pkgRoot = resolve(here, '..');
const repoRoot = resolve(pkgRoot, '..', '..');

const src = resolve(repoRoot, 'hardware', 'joint-map.json');
const dest = resolve(pkgRoot, 'dist', 'joint-map.json');

mkdirSync(dirname(dest), { recursive: true });
copyFileSync(src, dest);
console.error(`copied hardware/joint-map.json -> ${dest.slice(pkgRoot.length + 1)}`);
